#define _GNU_SOURCE
#include <errno.h>
#include <linux/filter.h>
#include <linux/seccomp.h>
#include <poll.h>
#include <signal.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/prctl.h>
#include <sys/ptrace.h>
#include <sys/resource.h>
#include <sys/signalfd.h>
#include <sys/syscall.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

#define REQUIRE(x) do { if (!(x)) { perror(#x); exit(1); } } while (0)
static double now(void) {
    struct timespec t;
    REQUIRE(!clock_gettime(CLOCK_MONOTONIC, &t));
    return t.tv_sec + t.tv_nsec / 1e9;
}
static double cpu_time(struct rusage *r) {
    return r->ru_utime.tv_sec + r->ru_stime.tv_sec +
        (r->ru_utime.tv_usec + r->ru_stime.tv_usec) / 1e6;
}
int main(int argc, char **argv) {
    REQUIRE(argc == 3);
    int polling = !strcmp(argv[1], "poll"), count = atoi(argv[2]);
    REQUIRE(polling || !strcmp(argv[1], "wait"));
    REQUIRE(count > 0);
    sigset_t signals;
    sigemptyset(&signals);
    sigaddset(&signals, SIGCHLD);
    REQUIRE(!sigprocmask(SIG_BLOCK, &signals, NULL));
    int fd = signalfd(-1, &signals, SFD_NONBLOCK | SFD_CLOEXEC);
    REQUIRE(fd >= 0);
    pid_t child = fork();
    REQUIRE(child >= 0);
    if (!child) {
        REQUIRE(!ptrace(PTRACE_TRACEME, 0, NULL, NULL));
        raise(SIGSTOP);
        struct sock_filter code[] = {
            BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
            BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, __NR_getpid, 0, 1),
            BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_TRACE),
            BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        };
        struct sock_fprog filter = { sizeof(code) / sizeof(code[0]), code };
        REQUIRE(!prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0));
        REQUIRE(!syscall(__NR_seccomp, SECCOMP_SET_MODE_FILTER, 0, &filter));
        for (int i = 0; i < count; ++i) REQUIRE(syscall(__NR_getpid) > 0);
        _exit(0);
    }
    int status;
    REQUIRE(waitpid(child, &status, 0) == child && WIFSTOPPED(status));
    REQUIRE(!ptrace(PTRACE_SETOPTIONS, child, NULL,
                    PTRACE_O_TRACESECCOMP | PTRACE_O_EXITKILL));
    double start = now();
    int stops = 0, waits = 0, polls = 0;
    REQUIRE(!ptrace(PTRACE_CONT, child, NULL, NULL));
    for (;;) {
        ++waits;
        pid_t got = waitpid(child, &status, polling ? WNOHANG : 0);
        if (got < 0 && errno == EINTR) continue;
        REQUIRE(got >= 0);
        if (!got) {
            struct signalfd_siginfo records[8];
            ssize_t bytes;
            while ((bytes = read(fd, records, sizeof(records))) > 0) {}
            REQUIRE(bytes < 0 && errno == EAGAIN);
            // Recheck after draining; coalesced SIGCHLD is only a hint.
            ++waits;
            got = waitpid(child, &status, WNOHANG);
            REQUIRE(got >= 0);
            if (!got) {
                struct pollfd event = { fd, POLLIN, 0 };
                ++polls;
                REQUIRE(ppoll(&event, 1, NULL, NULL) > 0);
                continue;
            }
        }
        if (WIFEXITED(status)) { REQUIRE(!WEXITSTATUS(status)); break; }
        REQUIRE(WIFSTOPPED(status) && (status >> 16) == PTRACE_EVENT_SECCOMP);
        ++stops;
        REQUIRE(!ptrace(PTRACE_CONT, child, NULL, NULL));
    }
    double elapsed = now() - start;
    struct rusage self, children;
    REQUIRE(!getrusage(RUSAGE_SELF, &self));
    REQUIRE(!getrusage(RUSAGE_CHILDREN, &children));
    REQUIRE(stops == count);
    printf("WAIT_BENCH mode=%s count=%d seconds=%.9f cpu=%.9f switches=%ld waits=%d polls=%d\n",
        argv[1], count, elapsed, cpu_time(&self) + cpu_time(&children),
        self.ru_nvcsw + self.ru_nivcsw + children.ru_nvcsw + children.ru_nivcsw,
        waits, polls);
    return 0;
}
